import java.util.*;class A{String s(boolean P,String[]I){List<Integer>a=new ArrayList<>(),b=new ArrayList<>();var c=new HashMap<Integer,Integer>();for(var l:I){var S=new Scanner(l);a.add(S.nextInt());int x=S.nextInt();b.add(x);c.merge(x,1,(u,v)->u+v);}long r=0;if(P){a.sort(null);b.sort(null);for(int i=a.size();i-->0;)r+=Math.abs(a.get(i)-b.get(i));}else for(int x:a)r+=(long)x*c.getOrDefault(x,0);return r+"";}}
